def minDeletionSize(A):
    n, m = len(A), len(A[0])

    @lru_cache(None)
    def dp(prev):
        if prev == m - 1:
            return 0

        keep = float('inf')
        if all(A[i][prev] <= A[i][prev + 1] for i in range(n)):
            keep = dp(prev + 1)

        delete = 1 + dp(prev + 1)

        return min(keep, delete)

    return dp(0)
